// n8n Code node — "Build LinkedIn Search URL"  [UPDATED 2026-07-11, rev 2]
// Mode: Run Once for All Items
//
// Input: items from Google Sheets, one row per title (column: "title").
//        Optional fixed/global filter fields read from a Filters node
//        (location, experience level, remote, job type, easy apply).
//
// Strategy: combine ALL titles from the sheet into ONE Boolean OR query
// (quoted exact phrases) rather than looping one search per title -- this
// produces PAGES_PER_RUN LinkedIn requests instead of N-per-title, keeping
// request volume down while still covering every title.
//
// ENDPOINT: uses the "jobs-guest" endpoint
// (linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search) rather than
// the full search page (linkedin.com/jobs/search/). CONFIRMED (2026-07):
// the unauthenticated full-page URL was tested directly against this
// project and hit LinkedIn's authwall (HTTP 999) even with browser-like
// headers. The two reference projects that DO use the full-page URL only
// work because they either (a) pay a third-party scraping API to do it, or
// (b) authenticate with a real logged-in session cookie -- neither is a
// URL-choice difference, and (b) specifically reintroduces the exact
// spoofed-Googlebot-UA + live-session-cookie exposure this project already
// tested and moved away from. Do not swap this endpoint without one of
// those two trade-offs being made deliberately, not as a side effect.
//
// PAGINATION [UPDATED 2026-07-11, rev 2]: previously hardcoded to start=0
// (page 1 only), capping real volume regardless of how many titles were
// OR'd together. RESULTS_PER_PAGE below is set to 10, matching the user's
// real, directly observed output (every run returns exactly 10 links, not
// the 25 first assumed in rev 1 -- that 25 was an unverified guess based
// on a generic LinkedIn page size and was wrong for this specific
// endpoint; corrected here based on actual observed behavior instead).
// This value is still not independently verified beyond that one
// observation -- if start=10 or start=20 return anything other than a
// fresh, non-overlapping batch of 10, this constant needs revisiting
// again. "Dedup Job Links" (new node, wired after Split Out) provides a
// safety net either way if pages ever do overlap.
//
// NOTE (verified, not assumed): on public LinkedIn job search, Boolean
// keywords match against the job DESCRIPTION, not the title/location
// fields specifically -- so this query may surface jobs that mention a
// title term in the body text even if their actual title differs. This
// is an accepted tradeoff for fewer, less bot-like requests.

const PAGES_PER_RUN = 3;       // start=0, 10, 20 -- ~30 postings/run instead of ~10
const RESULTS_PER_PAGE = 10;   // per user's directly observed real output, NOT independently re-verified

const titleRows = $input.all().map(item => item.json);

if (!titleRows.length) {
  throw new Error('No title rows received from Google Sheets input.');
}

// Build the quoted-OR keyword string: "Title A" OR "Title B" OR ...
const titles = titleRows
  .map(row => row.title)
  .filter(Boolean);

if (titles.length === 0) {
  throw new Error('No valid "title" values found in the input rows.');
}

const booleanKeywordQuery = titles
  .map(t => `"${t.replace(/"/g, '')}"`) // strip any stray quotes in the source data
  .join(' OR ');

// --- Fixed/global filters, read from Filters node (per user: NOT per-row) ---
const config = $('Filters').first()?.json || {};
const location = config.location || '';
const experienceLevel = config.experience_level || ''; // e.g. "Mid-Senior level"
const remote = config.remote || '';                     // e.g. "Remote,Hybrid"
const jobType = config.job_type || '';                  // e.g. "Full-time"
const easyApply = config.easy_apply === true ||
  String(config.easy_apply).trim().toLowerCase() === 'true';

function buildFilterSuffix() {
  let suffix = '';

  if (location) {
    suffix += `&location=${encodeURIComponent(location)}`;
  }

  if (experienceLevel) {
    const expLevelMap = {
      'Internship': '1',
      'Entry level': '2',
      'Associate': '3',
      'Mid-Senior level': '4',
      'Director': '5',
      'Executive': '6',
    };
    const transformed = experienceLevel
      .split(',')
      .map(e => expLevelMap[e.trim()] || '')
      .filter(Boolean);
    if (transformed.length) suffix += `&f_E=${transformed.join(',')}`;
  }

  if (remote) {
    const remoteMap = { 'On-Site': '1', 'Remote': '2', 'Hybrid': '3' };
    const transformed = remote
      .split(',')
      .map(e => remoteMap[e.trim()] || '')
      .filter(Boolean);
    if (transformed.length) suffix += `&f_WT=${transformed.join(',')}`;
  }

  if (jobType) {
    const jobTypeMap = {
      'Full-time': 'F', 'Part-time': 'P', 'Contract': 'C',
      'Temporary': 'T', 'Other': 'O', 'Internship': 'I',
    };
    const transformed = jobType
      .split(',')
      .map(t => jobTypeMap[t.trim()] || '')
      .filter(Boolean);
    if (transformed.length) suffix += `&f_JT=${transformed.join(',')}`;
  }

  if (easyApply) {
    // Verified parameter: f_EA=true shows only Easy Apply listings.
    suffix += '&f_EA=true';
  }

  return suffix;
}

const filterSuffix = buildFilterSuffix();
const keywordParam = `&keywords=${encodeURIComponent(booleanKeywordQuery)}`;

const pages = [];
for (let page = 0; page < PAGES_PER_RUN; page++) {
  const start = page * RESULTS_PER_PAGE;
  const url =
    `https://www.linkedin.com/jobs-guest/jobs/api/seeMoreJobPostings/search` +
    `?f_TPR=r604800&start=${start}${keywordParam}${filterSuffix}`;

  pages.push({
    json: {
      url,
      page_index: page,
      start,
      titles_combined: booleanKeywordQuery,
      title_count: titles.length,
    },
  });
}

return pages;

// n8n Code node — "Parse Applicant Count"
// Mode: Run Once for Each Item
// Place this after the HTML extraction node that pulls the raw
// "applicants" caption text from each job page.
//
// Converts raw text like "23 applicants" or "Over 100 applicants" into
// a structured field: a number when known exactly, or null + a flag when
// LinkedIn only shows the capped "Over 100" text. Filtering logic itself
// is deliberately NOT implemented here -- per project decision, this just
// captures the data; the actual "under 10" cutoff is a deferred decision.

const rawText = ($input.item.json.applicants_raw || '').trim();

let applicantCount = null;
let isCapped = false;

if (rawText) {
  const numberMatch = rawText.match(/(\d+)/);
  if (numberMatch) {
    applicantCount = parseInt(numberMatch[1], 10);
    isCapped = /over/i.test(rawText); // "Over 100 applicants" still has a number, but it's a floor, not exact
  }
}

return {
  json: {
    ...$input.item.json,
    applicant_count: applicantCount,   // number, or null if not found/parseable
    applicant_count_capped: isCapped,  // true if text said "Over X" (not exact)
    applicant_count_raw: rawText,      // keep original text for debugging/audit
  },
};

// n8n Code node — "Check Compile Result"
// Mode: Run Once for All Items
// Place immediately after "latex-api /convert".
// Inspects whether the compile succeeded (PDF binary present) or failed
// (422 + compiler log, surfaced via n8n's error-continuation output).

const item = $input.first();

if (item.json && item.json.error) {
  let compileError = null;
  let compileLog = null;
  let parseFailed = false;

  try {
    const rawMessage = item.json.error.message || '';
    const dashIndex = rawMessage.indexOf(' - ');
    const afterDash = dashIndex !== -1 ? rawMessage.slice(dashIndex + 3) : rawMessage;
    const innerJsonString = JSON.parse(afterDash);
    const parsed = JSON.parse(innerJsonString);
    compileError = parsed.detail?.error || null;
    compileLog = parsed.detail?.log || null;
  } catch (e) {
    parseFailed = true;
  }

  return [{
    json: {
      success: false,
      error_message: compileError || item.json.error.message || 'Unknown latex-api error',
      compile_log: compileLog ? compileLog.replace(/\\n/g, '\n').slice(0, 2000) : null,
      parse_failed: parseFailed,
    },
  }];
}

if (!item.binary || !item.binary.data) {
  return [{
    json: {
      success: false,
      error_message: 'latex-api returned no error but also no PDF binary.',
      compile_log: null,
    },
  }];
}

// --- Build the dynamic filename ---
const jobTitle = $('Extract Job Details').first().json.title || 'Untitled';
const company = $('Extract Job Details').first().json.company || 'UnknownCompany';

const sanitize = (s) => s
  .trim()
  .replace(/[\\/:*?"<>|]/g, '')   // strip filesystem-illegal characters
  .replace(/\s+/g, ' ');           // collapse repeated whitespace

const ownerName = ($('CV Generation Config').first().json.cv_owner_name || 'Candidate').trim();
const fileName = `${sanitize(ownerName)}- ${sanitize(jobTitle)}-${sanitize(company)}.pdf`;

return [{
  json: { success: true },
  binary: {
    data: {
      ...item.binary.data,
      fileName,
    },
  },
}];

